// Generated by vibelang from src/features/generated/contract.ts; the migrate flow writes it again with each batch.
// Generated files in a repository (docs/features/repo.md#generated-files): what marks a file as made by a flow rather
// than written by a person, and the words the view shows for it. Nothing here imports a library.
/**
 * Where a project declares its generated files, beside its `.smithers/` folder: a JSON object whose `outputs` maps each
 * output path, from that folder's parent, to the flow that produces it, its inputs, the cache key of the build it came
 * from, and the run that last produced it. The repository's root, or any project folder inside it, may hold one.
 */
export const MANIFEST_PATH = ".smithers/generated.json";
/** The manifest of the project folder `folder` (`""`: the repository's root). */
export const manifestIn = (folder) => (folder === "" ? MANIFEST_PATH : `${folder}/${MANIFEST_PATH}`);
/** The project folder a manifest at `path` belongs to: the folder holding its `.smithers/`. */
export const folderOf = (manifestPath) => manifestPath.slice(0, -(MANIFEST_PATH.length + 1));
/** The largest manifest the view reads; a bigger one marks nothing. */
export const MAX_MANIFEST_BYTES = 256 * 1024;
/** How many leading lines of a file a header marker may sit in. */
export const MARKER_LINES = 5;
/**
 * The header markers that say a file is generated, as tools write them: `@generated` (Meta's convention, which many
 * code generators follow) and Go's `Code generated … DO NOT EDIT.`. Detection reads a standalone `@generated` line or
 * the first content in a line, C-style block or HTML comment.
 */
export const MARKERS = [/^@generated\b/, /^Code generated\b.*\bDO NOT EDIT\b/i];
/** Where a repository's file flow lives: `.smithers/flows/<tag>/flow.ts` (M-49). */
export const flowPath = (tag) => `.smithers/flows/${tag}/flow.ts`;
/** The warning over a generated file someone edits. */
export const EDIT_SOURCE_INSTEAD = "Generated file: edits are overwritten. Edit its source instead.";
